import fs from 'fs';
import path from 'path';

interface StabilityResponse {
  image: string;
  finish_reason: string;
  seed: number;
}

async function generateImage(prompt: string, outputPath: string): Promise<void> {
  const formData = new FormData();
  formData.append('prompt', prompt);
  formData.append('output_format', 'png');
  formData.append('width', '1024');
  formData.append('height', '1024');

  const response = await fetch(
    'https://api.stability.ai/v2beta/stable-image/generate/core',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.STABILITY_API_KEY}`,
        Accept: 'application/json',
      },
      body: formData,
    }
  );

  if (!response.ok) {
    const error = await response.json();
    throw new Error(`Stability AI error ${response.status}: ${JSON.stringify(error)}`);
  }

  const data = (await response.json()) as StabilityResponse;

  // Response contains base64-encoded image
  const imageBuffer = Buffer.from(data.image, 'base64');
  fs.writeFileSync(outputPath, imageBuffer);

  console.log(`Image saved to ${outputPath} (seed: ${data.seed})`);
}

await generateImage(
  'A photorealistic red fox sitting in a snowy forest, golden hour lighting',
  path.join(process.cwd(), 'output.png')
);

import fs from 'fs';

async function removeBackground(
  inputImagePath: string,
  outputImagePath: string
): Promise<void> {
  const imageBuffer = fs.readFileSync(inputImagePath);
  const imageBlob = new Blob([imageBuffer], { type: 'image/png' });

  const formData = new FormData();
  formData.append('image', imageBlob, 'input.png');
  formData.append('output_format', 'png');

  const response = await fetch(
    'https://api.stability.ai/v2beta/stable-image/edit/remove-background',
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${process.env.STABILITY_API_KEY}`,
        Accept: 'application/json',
      },
      body: formData,
    }
  );

  if (!response.ok) {
    const error = await response.json();
    throw new Error(`Background removal failed ${response.status}: ${JSON.stringify(error)}`);
  }

  const data = (await response.json()) as { image: string; finish_reason: string };
  const outputBuffer = Buffer.from(data.image, 'base64');
  fs.writeFileSync(outputImagePath, outputBuffer);

  console.log(`Background removed. Saved to ${outputImagePath}`);
}

await removeBackground('product.png', 'product-nobg.png');
